export interface GoogleMeetConfig {
  /** Stable, non-secret label for one authenticated Google account. */
  sourceId: string
  /** Journal identities use this prefix; change it for a separate installation. */
  streamPrefix: string
  database: string
  /** Re-read recent completed calls and their children; defaults to 24 hours. */
  lookbackHours: number
  /** Small discovery pages bound how many conferences replay after interruption. */
  pageSize: number
  maxChunks: number
}

/** Runtime settings; the exported destination schemas use database at setup time. */
export type GoogleMeetReaderConfig = Omit<GoogleMeetConfig, 'database'>

// Set schema placement before importing index.ts. Credentials are read at request time.
export const googleMeetConfig: GoogleMeetConfig = {
  sourceId: 'google-meet.primary',
  streamPrefix: 'google-meet',
  database: 'default',
  lookbackHours: 24,
  pageSize: 1,
  maxChunks: 200,
}

import { HttpError, IngestConfigError, paginate, type ErrorClassifier, type FetchContext } from '@chkit/plugin-ingest'

import { googleMeetConfig, type GoogleMeetReaderConfig } from './config.js'

export interface Named { name: string; [key: string]: unknown }
export interface CollectionCursor { pageToken?: string; recoveryCount?: number }
interface CollectionOptions { filter?: string; initial?: CollectionCursor; pageSize?: number }

export interface GoogleMeetClientDeps {
  config: GoogleMeetReaderConfig
  fetch: (url: string, init: RequestInit) => Promise<Response>
  token: () => string | undefined
}

export const defaultGoogleMeetClientDeps: GoogleMeetClientDeps = {
  config: googleMeetConfig,
  fetch: (url, init) => fetch(url, init),
  token: () => process.env.GOOGLE_MEET_ACCESS_TOKEN,
}

export const classifyGoogleMeetError: ErrorClassifier = (cause) =>
  cause instanceof IngestConfigError || cause instanceof SyntaxError ? { kind: 'permanent' } : undefined

export function readCollection(context: FetchContext, path: string, field: string, deps: GoogleMeetClientDeps, options: CollectionOptions = {}) {
  return paginate<Named, CollectionCursor, { reset: true }>({
    context, initial: options.initial ?? {}, label: `GET ${field}`,
    fetchPage: async (cursor, signal) => {
      const current = cursor ?? {}
      const page = await requestPage(path, field, current.pageToken, options.filter, options.pageSize ?? 100, signal, deps)
      if ('reset' in page) {
        if (current.recoveryCount) throw new IngestConfigError(`Meet ${field} repeatedly rejected its page token. Increase the execution budget or migrate the checkpoint after reviewing coverage.`)
        return { items: [], next: { recoveryCount: 1 }, metadata: { reset: true } }
      }
      return { items: page.items, next: page.nextPageToken ? { ...current, pageToken: page.nextPageToken } : undefined }
    },
  })
}

export function optionalString(value: unknown, field: string): string | undefined {
  if (value === undefined) return undefined
  if (typeof value !== 'string' || !value.trim()) throw new IngestConfigError(`Meet ${field} must be a non-empty string.`)
  return value
}

export function optionalTimestamp(value: unknown, field: string): string | undefined {
  return value === undefined ? undefined : timestamp(value, field)
}

export function timestamp(value: unknown, field: string): string {
  const result = optionalString(value, field)
  if (!result || !Number.isFinite(Date.parse(result))) throw new IngestConfigError(`Meet ${field} is not a timestamp.`)
  return result
}

export function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

async function requestPage(path: string, field: string, pageToken: string | undefined, filter: string | undefined, pageSize: number, signal: AbortSignal, deps: GoogleMeetClientDeps): Promise<{ items: Named[]; nextPageToken?: string } | { reset: true }> {
  const token = deps.token()?.trim()
  if (!token) throw new IngestConfigError('Set GOOGLE_MEET_ACCESS_TOKEN.')
  const url = new URL(`https://meet.googleapis.com/v2/${path}`)
  url.searchParams.set('pageSize', String(pageSize))
  if (filter) url.searchParams.set('filter', filter)
  if (pageToken) url.searchParams.set('pageToken', pageToken)
  const response = await deps.fetch(url.toString(), { signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]), headers: { Authorization: `Bearer ${token}` }, redirect: 'error' })
  if (pageToken && (response.status === 400 || response.status === 410)) {
    const detail = await response.clone().text()
    if (/page[_\s-]*token/i.test(detail) && /invalid|expir/i.test(detail)) return { reset: true }
  }
  if (!response.ok) throw await HttpError.fromResponse(response)
  const payload: unknown = await response.json()
  if (!isObject(payload) || payload[field] !== undefined && !Array.isArray(payload[field])) throw new IngestConfigError(`Meet ${field} is not an array.`)
  const values = payload[field] ?? []
  if (!Array.isArray(values) || values.length > pageSize) throw new IngestConfigError(`Meet ${field} exceeded the requested page size.`)
  const items = values.map((value: unknown): Named => {
    if (!isObject(value)) throw new IngestConfigError('Meet returned an invalid resource.')
    const name = optionalString(value.name, 'resource name')
    if (!name || (field === 'conferenceRecords' ? !/^conferenceRecords\/[^/?#]+$/.test(name) : !name.startsWith(`${path}/`) || name.slice(path.length + 1).includes('/') || /[?#]/.test(name))) throw new IngestConfigError(`Meet ${field} returned a resource outside its requested parent.`)
    return { ...value, name }
  })
  return { items, nextPageToken: optionalString(payload.nextPageToken, 'nextPageToken') }
}

import { cursorState, definePipeline, defineStream, IngestConfigError } from '@chkit/plugin-ingest'

import { classifyGoogleMeetError, defaultGoogleMeetClientDeps, type GoogleMeetClientDeps } from './client.js'
import { googleMeetConfig, type GoogleMeetReaderConfig } from './config.js'
import { google_meet_conferencesRaw, google_meet_transcriptsRaw, google_meet_transcriptEntriesRaw, google_meet_participantsRaw, google_meet_participantSessionsRaw, google_meet_recordingsRaw, parseMeetState, readResource, type MeetSelection, type MeetState, type Resource } from './sources/resources.js'

export function createGoogleMeetPipeline(config: GoogleMeetReaderConfig = googleMeetConfig, deps: GoogleMeetClientDeps = defaultGoogleMeetClientDeps) {
  const boundConfig = { ...config }
  if (!boundConfig.sourceId.trim() || !boundConfig.streamPrefix.trim()) throw new IngestConfigError('Meet sourceId and streamPrefix must be non-empty strings.')
  if (!Number.isFinite(boundConfig.lookbackHours) || boundConfig.lookbackHours <= 0) throw new IngestConfigError('Meet lookbackHours must be positive.')
  if (!Number.isSafeInteger(boundConfig.pageSize) || boundConfig.pageSize <= 0 || boundConfig.pageSize > 100) throw new IngestConfigError('Meet pageSize must be an integer between one and 100.')
  if (!Number.isSafeInteger(boundConfig.maxChunks) || boundConfig.maxChunks <= 0) throw new IngestConfigError('Meet maxChunks must be a positive safe integer.')
  const client = { ...deps, config: boundConfig }
  return definePipeline({
    id: boundConfig.streamPrefix, tags: ['provider:google-meet'], maxStreams: 1, maxFetches: 1,
    streams: [
      resourceStream('conferences', google_meet_conferencesRaw, client),
      resourceStream('transcripts', google_meet_transcriptsRaw, client),
      resourceStream('transcript-entries', google_meet_transcriptEntriesRaw, client),
      resourceStream('participants', google_meet_participantsRaw, client),
      resourceStream('participant-sessions', google_meet_participantSessionsRaw, client),
      resourceStream('recordings', google_meet_recordingsRaw, client),
    ],
  })
}

export const google_meetPipeline = createGoogleMeetPipeline()

function resourceStream(resource: Resource, destination: typeof google_meet_conferencesRaw, deps: GoogleMeetClientDeps) {
  const config = deps.config
  const checkpoint = cursorState({ id: `${config.streamPrefix}.${resource}.pages`, version: 2, parse: (raw) => parseMeetState(raw, config) })
  return defineStream<Record<string, unknown>, MeetState, MeetSelection>({
    id: `${config.streamPrefix}.${resource}`, tags: [`resource:${resource}`], destination,
    incremental: {
      id: checkpoint.id, version: checkpoint.version, parseState: checkpoint.parseState,
      plan: ({ range }) => range,
    },
    batchSize: 1,
    budget: { maxChunks: config.maxChunks, maxChunkRows: 100 },
    classifyError: classifyGoogleMeetError,
    read: (context) => readResource(context, resource, deps),
  })
}

import { IngestConfigError, rawRows, rawTable, type ReadContext, type SourceChunk } from '@chkit/plugin-ingest'

import { isObject, optionalString, optionalTimestamp, readCollection, timestamp, type CollectionCursor, type GoogleMeetClientDeps, type Named } from '../client.js'
import { googleMeetConfig, type GoogleMeetReaderConfig } from '../config.js'

const hourMs = 3_600_000

export type Resource = 'conferences' | 'transcripts' | 'transcript-entries' | 'participants' | 'participant-sessions' | 'recordings'
interface Bounds { from?: string; to?: string }
interface Window extends CollectionCursor { from: string; to: string; phase: 'ended' | 'ongoing' }
export interface MeetState { scope: string; watermark?: string; bounds?: Bounds; window?: Window }
export type MeetSelection = { from: Date | undefined; to: Date | undefined } | undefined
type MeetContext = ReadContext<MeetSelection, MeetState>
type MeetChunk = SourceChunk<Record<string, unknown>, MeetState>

export const google_meet_conferencesRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_conferences_raw' })
export const google_meet_transcriptsRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_transcripts_raw' })
export const google_meet_transcriptEntriesRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_transcript_entries_raw' })
export const google_meet_participantsRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_participants_raw' })
export const google_meet_participantSessionsRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_participant_sessions_raw' })
export const google_meet_recordingsRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_recordings_raw' })

// Every resource independently discovers conferences and replays unfinished parent pages.
export async function* readResource(context: MeetContext, resource: Resource, deps: GoogleMeetClientDeps): AsyncGenerator<MeetChunk> {
  const scope = meetScope(deps.config)
  let state: MeetState = context.state ?? { scope }
  const requestedBounds = context.selection?.from || context.selection?.to
    ? { from: context.selection.from?.toISOString(), to: context.selection.to?.toISOString() }
    : undefined
  if (requestedBounds && state.bounds && JSON.stringify(requestedBounds) !== JSON.stringify(state.bounds)) throw new IngestConfigError('Meet backfill bounds changed. Use a new backfill ID.')
  if (requestedBounds && state.watermark && !state.bounds) throw new IngestConfigError('Meet checkpoint was created without date bounds. Use a new backfill ID.')
  state = { ...state, bounds: state.bounds ?? requestedBounds }
  if (!state.window) {
    const to = state.bounds?.to ?? context.cutoff.toISOString()
    const anchor = state.watermark ?? to
    const from = state.bounds?.from ?? new Date(Date.parse(anchor) - deps.config.lookbackHours * hourMs).toISOString()
    if (Date.parse(from) > Date.parse(to) || state.watermark && Date.parse(state.watermark) > Date.parse(to)) throw new IngestConfigError('Meet cutoff precedes its committed range.')
    state = { ...state, window: { from, to, phase: 'ended' } }
    yield progress(state)
  }
  while (state.window) {
    const window = state.window
    const filter = window.phase === 'ended'
      ? `end_time>="${window.from}" AND end_time<="${window.to}"`
      : `end_time IS NULL AND start_time<="${window.to}"`
    for await (const page of readCollection(context, 'conferenceRecords', 'conferenceRecords', deps, { filter, initial: { pageToken: window.pageToken, recoveryCount: window.recoveryCount }, pageSize: deps.config.pageSize })) {
      if (!page.metadata?.reset) {
        for (const conference of page.items) {
          if (resource === 'conferences') yield { rows: rawRows([conference], (item) => JSON.stringify([deps.config.sourceId, item.name])) }
          else yield* readChildren(context, resource, conference, deps)
        }
      }
      state = page.next
        ? { ...state, window: { from: window.from, to: window.to, phase: window.phase, ...page.next } }
        : window.phase === 'ended' && !state.bounds
          ? { ...state, window: { from: window.from, to: window.to, phase: 'ongoing' } }
          : { scope, bounds: state.bounds, watermark: window.to }
      // Flush all child rows before advancing discovery. Partial pages replay on resume.
      yield progress(state)
    }
  }
}

export function parseMeetState(raw: unknown, config: GoogleMeetReaderConfig): MeetState {
  const scope = meetScope(config)
  if (!isObject(raw) || raw.scope !== scope || 'pending' in raw || 'cycle' in raw || 'active' in raw) throw new IngestConfigError('Meet checkpoint scope or format changed. Migrate the state explicitly or use a new stream ID.')
  const state: MeetState = { scope, watermark: optionalTimestamp(raw.watermark, 'watermark') }
  if (raw.bounds !== undefined) {
    if (!isObject(raw.bounds)) throw new IngestConfigError('Meet backfill bounds are invalid.')
    state.bounds = { from: optionalTimestamp(raw.bounds.from, 'backfill from'), to: optionalTimestamp(raw.bounds.to, 'backfill to') }
    if (!state.bounds.from && !state.bounds.to || state.bounds.from && state.bounds.to && Date.parse(state.bounds.from) > Date.parse(state.bounds.to)) throw new IngestConfigError('Meet backfill bounds are invalid.')
  }
  if (raw.window !== undefined) {
    const window = raw.window
    if (!isObject(window) || window.phase !== 'ended' && window.phase !== 'ongoing' || state.bounds && window.phase === 'ongoing') throw new IngestConfigError('Meet discovery window is invalid.')
    const from = timestamp(window.from, 'window from')
    const to = timestamp(window.to, 'window to')
    if (Date.parse(from) > Date.parse(to) || state.bounds?.from && from !== state.bounds.from || state.bounds?.to && to !== state.bounds.to) throw new IngestConfigError('Meet discovery bounds are invalid.')
    if (window.recoveryCount !== undefined && window.recoveryCount !== 1) throw new IngestConfigError('Meet recovery count must be one.')
    state.window = { from, to, phase: window.phase, pageToken: optionalString(window.pageToken, 'pageToken'), recoveryCount: window.recoveryCount }
  }
  if (!state.window && !state.watermark) throw new IngestConfigError('Meet checkpoint has no discovery progress.')
  return state
}

async function* readChildren(context: MeetContext, resource: Exclude<Resource, 'conferences'>, conference: Named, deps: GoogleMeetClientDeps): AsyncGenerator<MeetChunk> {
  const collection = resource === 'transcript-entries' ? 'transcripts' : resource === 'participant-sessions' ? 'participants' : resource
  for await (const page of readCollection(context, `${conference.name}/${collection}`, collection, deps)) {
    if (resource === 'transcript-entries' || resource === 'participant-sessions') {
      const child = resource === 'transcript-entries' ? 'entries' : 'participantSessions'
      const field = resource === 'transcript-entries' ? 'transcriptEntries' : child
      const parentField = resource === 'transcript-entries' ? 'transcript_name' : 'participant_name'
      for (const parent of page.items) {
        for await (const children of readCollection(context, `${parent.name}/${child}`, field, deps)) {
          yield { rows: rawRows(children.items.map((item) => ({ ...item, conference_name: conference.name, [parentField]: parent.name })), (item) => JSON.stringify([deps.config.sourceId, item.name])) }
        }
      }
      if (!page.items.length) yield { rows: [] }
    } else {
      yield { rows: rawRows(page.items.map((item) => ({ ...item, conference_name: conference.name })), (item) => JSON.stringify([deps.config.sourceId, item.name])) }
    }
  }
}

function progress(state: MeetState): MeetChunk {
  return { rows: [], state, id: 'meet-discovery-progress' }
}

function meetScope(config: GoogleMeetReaderConfig): string {
  return JSON.stringify([config.sourceId, config.lookbackHours, config.pageSize])
}

import { expect, test } from 'bun:test'
import { runIngestion, selectStreams } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { googleMeetConfig } from '../config.js'
import { createGoogleMeetPipeline } from '../pipeline.js'
import { parseMeetState, type Resource } from '../sources/resources.js'

const cutoff = new Date('2026-10-05T00:00:00Z')
const conference = { name: 'conferenceRecords/c1', startTime: '2026-10-02T00:00:00Z', endTime: '2026-10-04T12:00:00Z', expireTime: '2026-11-03T12:00:00Z' }
const transcript = { name: `${conference.name}/transcripts/t1`, state: 'FILE_GENERATED' }
const entry = { name: `${transcript.name}/entries/e1`, text: 'first' }
const participant = { name: `${conference.name}/participants/p1`, signedinUser: { user: 'users/u1' } }
const session = { name: `${participant.name}/participantSessions/s1`, startTime: conference.startTime }
const recording = { name: `${conference.name}/recordings/r1`, state: 'FILE_GENERATED', driveDestination: { file: 'drive-file-1' } }
const resources: readonly Resource[] = ['conferences', 'transcripts', 'transcript-entries', 'participants', 'participant-sessions', 'recordings']

test('Meet replays an unfinished discovery page and its entries under the original window', async () => {
  const urls: URL[] = []
  const pipeline = fixturePipeline((url) => { urls.push(url); return fixture(url) })
  const initial = createMemoryJournal()
  const destination = createMemoryDestination()
  const first = await runIngestion(request(pipeline, 'transcript-entries', 2), { journal: initial, destination, now: () => cutoff })
  expect(first.streams[0]?.outcome).toBe('budget_exhausted')
  const checkpoint = await initial.readCheckpoint('google-meet.transcript-entries')
  expect(checkpoint.envelope?.state).toMatchObject({ window: { from: '2026-10-04T00:00:00.000Z', to: cutoff.toISOString(), phase: 'ended' } })
  expect(checkpoint.envelope?.state).not.toHaveProperty('watermark')
  expect(checkpoint.envelope?.state).not.toHaveProperty('active')
  const previous = urls.length
  const journal = restoredJournal(initial)
  const resumed = await runIngestion(request(pipeline), { journal, destination, now: () => new Date('2026-10-06T00:00:00Z') })
  expect(resumed.ok, JSON.stringify(resumed)).toBe(true)
  expect(urls[previous]?.pathname).toBe('/v2/conferenceRecords')
  expect(urls[previous]?.searchParams.get('filter')).toBe(urls[0]?.searchParams.get('filter'))
  expect(urls[previous + 1]?.pathname).toBe(`/v2/${conference.name}/transcripts`)
  expect(urls[previous + 2]?.searchParams.has('pageToken')).toBe(false)
  expect(new Set(destination.tables.get('default.google_meet_transcript_entries_raw')?.map((row) => row.id)).size).toBe(2)
  expect((await journal.readCheckpoint('google-meet.transcript-entries')).envelope?.state).toMatchObject({ watermark: cutoff.toISOString() })
})

test('Meet completes every parent on a discovery page before saving its continuation', async () => {
  const other = { ...conference, name: 'conferenceRecords/c2' }
  const urls: URL[] = []
  const pipeline = fixturePipeline((url) => {
    urls.push(url)
    if (url.pathname === '/v2/conferenceRecords') return Response.json({ conferenceRecords: url.searchParams.get('filter')?.includes('IS NULL') ? [] : [conference, other] })
    return fixture(url)
  }, { ...googleMeetConfig, pageSize: 2 })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'transcript-entries', 3), { journal, destination, now: () => cutoff })).streams[0]?.outcome).toBe('budget_exhausted')
  expect((await journal.readCheckpoint('google-meet.transcript-entries')).envelope?.state).toHaveProperty('window')
  const previous = urls.length
  expect((await runIngestion(request(pipeline), { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(urls.slice(previous).some((url) => url.pathname === `/v2/${other.name}/transcripts`)).toBe(true)
  expect(new Set(destination.tables.get('default.google_meet_transcript_entries_raw')?.map((row) => row.id)).size).toBe(4)
})

test('Meet resumes at the next discovery page after completing an earlier parent', async () => {
  const other = { ...conference, name: 'conferenceRecords/c2' }
  const urls: URL[] = []
  const pipeline = fixturePipeline((url) => {
    urls.push(url)
    if (url.pathname === '/v2/conferenceRecords') return Response.json(url.searchParams.get('filter')?.includes('IS NULL') ? { conferenceRecords: [] } : url.searchParams.has('pageToken')
      ? { conferenceRecords: [other] } : { conferenceRecords: [conference], nextPageToken: 'parents-next' })
    return fixture(url)
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'transcript-entries', 4), { journal, destination, now: () => cutoff })).streams[0]?.outcome).toBe('budget_exhausted')
  expect((await journal.readCheckpoint('google-meet.transcript-entries')).envelope?.state).toMatchObject({ window: { pageToken: 'parents-next' } })
  const previous = urls.length
  expect((await runIngestion(request(pipeline), { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(urls[previous]?.searchParams.get('pageToken')).toBe('parents-next')
  expect(urls.slice(previous).some((url) => url.pathname.startsWith(`/v2/${conference.name}/`))).toBe(false)
  expect(new Set(destination.tables.get('default.google_meet_transcript_entries_raw')?.map((row) => row.id)).size).toBe(4)
})

test('Meet replays child rows after lost destination acknowledgement without advancing discovery', async () => {
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const failed = await runIngestion(request(pipeline), { journal, destination: {
    async insert(input) {
      await destination.insert(input)
      if (input.rows.some((row) => JSON.stringify(row.raw).includes('second'))) throw new Error('lost acknowledgement')
    },
  }, now: () => cutoff })
  expect(failed.ok).toBe(false)
  expect((await journal.readCheckpoint('google-meet.transcript-entries')).envelope?.state).toHaveProperty('window')
  expect((await journal.readCheckpoint('google-meet.transcript-entries')).envelope?.state).not.toHaveProperty('watermark')
  expect((await runIngestion(request(pipeline), { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(new Set(destination.tables.get('default.google_meet_transcript_entries_raw')?.map((row) => row.id)).size).toBe(2)
})

test('Meet replay publishes changed child content under the same raw identity', async () => {
  let changed = false
  const pipeline = fixturePipeline((url) => url.pathname.endsWith('/entries') && !url.searchParams.has('pageToken')
    ? Response.json({ transcriptEntries: [{ ...entry, text: changed ? 'revised' : 'first' }], nextPageToken: 'entries-next' })
    : fixture(url))
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'transcript-entries', 2), { journal, destination, now: () => cutoff })).streams[0]?.outcome).toBe('budget_exhausted')
  changed = true
  expect((await runIngestion(request(pipeline), { journal, destination, now: () => cutoff })).ok).toBe(true)
  const versions = destination.tables.get('default.google_meet_transcript_entries_raw')?.filter((row) => row.id === JSON.stringify([googleMeetConfig.sourceId, entry.name]))
  expect(versions?.map((row) => row.raw)).toEqual([
    { ...entry, conference_name: conference.name, transcript_name: transcript.name },
    { ...entry, text: 'revised', conference_name: conference.name, transcript_name: transcript.name },
  ])
})

test('Meet discovers the preceding 24 hours by end time and also includes ongoing calls', async () => {
  const urls: URL[] = []
  const ongoing = { ...conference, name: 'conferenceRecords/ongoing', endTime: undefined }
  const pipeline = fixturePipeline((url) => {
    urls.push(url)
    return Response.json({ conferenceRecords: url.searchParams.get('filter')?.includes('IS NULL') ? [ongoing] : [conference] })
  })
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'conferences'), { journal: createMemoryJournal(), destination, now: () => cutoff })).ok).toBe(true)
  expect(urls.map((url) => url.searchParams.get('filter'))).toEqual([
    'end_time>="2026-10-04T00:00:00.000Z" AND end_time<="2026-10-05T00:00:00.000Z"',
    'end_time IS NULL AND start_time<="2026-10-05T00:00:00.000Z"',
  ])
  expect(urls.map((url) => url.searchParams.get('pageSize'))).toEqual(['1', '1'])
  expect(destination.tables.get('default.google_meet_conferences_raw')).toHaveLength(2)
})

test('Meet catches up from its completed watermark while rereading a 24-hour overlap', async () => {
  const filters: Array<string | null> = []
  const pipeline = fixturePipeline((url) => { filters.push(url.searchParams.get('filter')); return Response.json({ conferenceRecords: [] }) })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'conferences'), { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect((await runIngestion(request(pipeline, 'conferences'), { journal, destination, now: () => new Date('2026-10-07T00:00:00Z') })).ok).toBe(true)
  expect(filters[2]).toBe('end_time>="2026-10-04T00:00:00.000Z" AND end_time<="2026-10-07T00:00:00.000Z"')
})

test('Meet discovers a late transcript within the lookback without a not-ready placeholder', async () => {
  let ready = false
  const pipeline = fixturePipeline((url) => url.pathname.endsWith('/transcripts') && !ready ? Response.json({ transcripts: [] }) : fixture(url))
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline), { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(destination.tables.size).toBe(0)
  ready = true
  expect((await runIngestion(request(pipeline), { journal, destination, now: () => new Date('2026-10-05T06:00:00Z') })).ok).toBe(true)
  expect(new Set(destination.tables.get('default.google_meet_transcript_entries_raw')?.map((row) => row.id)).size).toBe(2)
})

test('Meet does not retain old conference IDs after they leave discovery', async () => {
